const input=$json.body??$json;
const outcome=String(input.outcome_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closeDate=String(input.closing_date??input.actual_closing_date??'').trim();
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const fundingReady=Boolean(input.funding_confirmed===true||String(input.funding_status??'').toLowerCase()==='funded');
const titleReady=Boolean(input.title_cleared===true||String(input.title_status??'').toLowerCase()==='cleared');
const executed=Boolean(input.executed_agreement===true||String(input.agreement_status??'').toLowerCase()==='executed');
const gross=Number(input.gross_profit??input.gross_assignment_profit??0);
const costs=Number(input.closing_costs??input.transaction_costs??0);
const net=Number(input.net_profit??(gross-costs));
const profitInputsValid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
let close_status='needs_review',next='WF-126',reason='verified close and profit reconciliation requires review';
if(input.dnc===true){close_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){close_status='blocked';reason='active closing blockers';}
else if(!dealId||!leadId||!propertyId){close_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(outcome!=='closing_outcome_ready'){close_status='outcome_not_ready';next='WF-327';reason='final closing outcome is not confirmed';}
else if(!executed){close_status='execution_missing';next='WF-322';reason='executed agreement evidence missing';}
else if(!fundingReady||!titleReady){close_status='funding_title_incomplete';next='WF-327';reason='funding or title confirmation missing';}
else if(!closeDate){close_status='closing_date_missing';reason='actual closing date missing';}
else if(!profitInputsValid){close_status='profit_inputs_invalid';reason='profit or closing cost inputs are invalid';}
else if(net<0){close_status='negative_profit_review';next='WF-329';reason='verified close has negative net profit and requires review';}
else{close_status='verified_close';next='WF-329';reason='closing execution, funding, title, date and profit reconcile successfully';}
return [{json:{...input,workflow_id:'WF-328',workflow_name:'Final Closing Outcome → Verified Close, Profit Reconciliation & CRM Closeout Controller',close_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,actual_closing_date:closeDate||null,funding_confirmed:fundingReady,title_cleared:titleReady,executed_agreement:executed,gross_profit:gross,closing_costs:costs,net_profit:net,profit_inputs_valid:profitInputsValid,next_workflow:next,human_review_required:close_status!=='verified_close',crm_activity:{activity_type:'verified_close_profit_reconciliation',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:close_status,closing_date:closeDate||null,gross_profit:gross,closing_costs:costs,net_profit:net,reason}}}];
